public class Main {
    public static void main(String[] args) {
        Pizza pizza = new Pizza.Builder("large").cheese(true).toppings(3).build();
        System.out.println(pizza);
    }
}

class Pizza {
    private final String size;
    private final boolean cheese;
    private final int toppings;

    private Pizza(Builder b) {
        this.size = b.size;
        this.cheese = b.cheese;
        this.toppings = b.toppings;
    }

    @Override
    public String toString() {
        return size + " pizza, cheese=" + cheese + ", toppings=" + toppings;
    }

    static class Builder {
        private final String size;
        private boolean cheese;
        private int toppings;

        Builder(String size) {
            this.size = size;
        }

        Builder cheese(boolean cheese) {
            this.cheese = cheese;
            return this;
        }

        Builder toppings(int toppings) {
            this.toppings = toppings;
            return this;
        }

        Pizza build() {
            return new Pizza(this);
        }
    }
}
